package com.lacoste.auto;
import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.view.Gravity;import android.widget.*;import android.content.Intent;
public class ActivationActivity extends Activity{
 private EditText chave; private TextView detalhe;
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(40,50,40,40);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setBackgroundColor(Color.rgb(15,20,32));TextView t=new TextView(this);t.setText("LACOSTE AUTO");t.setTextSize(24);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);root.addView(t);TextView info=new TextView(this);info.setText("Introduza a chave para enviar o pedido de licença. A ativação depende da aprovação no painel.");info.setTextColor(Color.LTGRAY);info.setPadding(0,20,0,20);root.addView(info);TextView id=new TextView(this);id.setText("ID do dispositivo: "+ApiClient.obterAndroidId(this));id.setTextColor(Color.LTGRAY);root.addView(id);chave=new EditText(this);chave.setHint("Chave de licença");chave.setSingleLine(true);chave.setTextColor(Color.WHITE);chave.setHintTextColor(Color.GRAY);root.addView(chave,new LinearLayout.LayoutParams(-1,60));Button enviar=new Button(this);enviar.setText("Permitir / enviar pedido");enviar.setAllCaps(false);root.addView(enviar,new LinearLayout.LayoutParams(-1,60));detalhe=new TextView(this);detalhe.setTextColor(Color.LTGRAY);detalhe.setPadding(0,20,0,0);root.addView(detalhe);enviar.setOnClickListener(v->{String c=chave.getText().toString().trim().toUpperCase();if(c.isEmpty()){detalhe.setText("Digite a chave.");return;}detalhe.setText("A enviar pedido...");LicenseManager.solicitar(this,c,(ok,msg)->runOnUiThread(()->{detalhe.setText(msg);if(ok&&LicenseManager.estaAtivado(this)){startActivity(new Intent(this,MainActivity.class));finish();}}));});setContentView(root);LicenseManager.verificarOnline(this,(ok,msg)->runOnUiThread(()->{if(ok&&LicenseManager.estaAtivado(this)){startActivity(new Intent(this,MainActivity.class));finish();}}));}
}
